export function Hydration({
  stage = "{{stage}}",
  buttonLabel = "{{buttonLabel}}",
  accent = "{{accent}}",
  showJsBadge = {{showJsBadge}},
}) {
  const hydrated = stage === "hydrated";
  return (
    <div role="status" style={{ font: "13px/1.5 system-ui, sans-serif", color: "#241430", background: "#FAF7F2", padding: 18, borderRadius: 12, width: 280, boxSizing: "border-box" }}>
      <p style={{ margin: "0 0 12px", fontSize: 12 }}>Stage: <strong>{hydrated ? "hydrated (interactive)" : "server HTML (static)"}</strong></p>
      <button type="button" style={{ border: "none", padding: "10px 18px", borderRadius: 8, fontWeight: 600, fontSize: 13, color: "#241430", width: "100%", background: hydrated ? accent : "#24143020", cursor: hydrated ? "pointer" : "default", opacity: hydrated ? 1 : .6 }}>{buttonLabel}</button>
      {showJsBadge && <p style={{ margin: "10px 0 0", fontSize: 10, color: "#24143099" }}>{hydrated ? "JS: event listeners attached" : "JS: not yet attached"}</p>}
    </div>
  );
}
